import {t,getLanguage} from './i18n.js';
const encoder=new TextEncoder();
export function zipStore(files){const chunks=[],directory=[];let offset=0;const crc=bytes=>{let c=0xffffffff;for(const b of bytes){c^=b;for(let i=0;i<8;i++)c=(c>>>1)^((c&1)?0xedb88320:0);}return (c^0xffffffff)>>>0;};for(const [name,content] of Object.entries(files)){const n=encoder.encode(name),b=typeof content==='string'?encoder.encode(content):content,h=new Uint8Array(30+n.length),v=new DataView(h.buffer),sum=crc(b);v.setUint32(0,0x04034b50,true);v.setUint16(4,20,true);v.setUint16(6,0x800,true);v.setUint32(14,sum,true);v.setUint32(18,b.length,true);v.setUint32(22,b.length,true);v.setUint16(26,n.length,true);h.set(n,30);chunks.push(h,b);const d=new Uint8Array(46+n.length),dv=new DataView(d.buffer);dv.setUint32(0,0x02014b50,true);dv.setUint16(4,20,true);dv.setUint16(6,20,true);dv.setUint16(8,0x800,true);dv.setUint32(16,sum,true);dv.setUint32(20,b.length,true);dv.setUint32(24,b.length,true);dv.setUint16(28,n.length,true);dv.setUint32(42,offset,true);d.set(n,46);directory.push(d);offset+=h.length+b.length;}const size=directory.reduce((s,b)=>s+b.length,0),end=new Uint8Array(22),v=new DataView(end.buffer);v.setUint32(0,0x06054b50,true);v.setUint16(8,directory.length,true);v.setUint16(10,directory.length,true);v.setUint32(12,size,true);v.setUint32(16,offset,true);return new Blob([...chunks,...directory,end],{type:'application/zip'});}
export async function exportGodot(state,image,vertices,width,height){
 const license=await fetch('./godot/LICENSE.txt');if(!license.ok)throw Error('Could not load the runtime license.');
 const runtime=await fetch('./godot/paper_wind.gd');if(!runtime.ok)throw Error(t('Godot 실행 스크립트를 읽지 못했습니다.'));
 const canvas=document.createElement('canvas');canvas.width=image.naturalWidth;canvas.height=image.naturalHeight;canvas.getContext('2d').drawImage(image,0,0);const png=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!png)throw Error(t('이미지를 PNG로 변환하지 못했습니다.'));
 const data={version:1,settings:{...state.settings},folds:state.folds,pins:state.pins,size:[width,height],vertices:vertices.map(p=>[p.u,p.v])};
 const scene='[gd_scene load_steps=2 format=3]\n\n[ext_resource type="Script" path="paper_wind.gd" id="1"]\n\n[node name="PaperWind" type="MeshInstance3D"]\nscript = ExtResource("1")\n';
 const demo='[gd_scene load_steps=3 format=3]\n\n[ext_resource type="PackedScene" path="paper_wind.tscn" id="1"]\n[sub_resource type="Environment" id="Env"]\nbackground_mode = 1\nbackground_color = Color(0.08, 0.12, 0.10, 1)\nambient_light_source = 3\nambient_light_color = Color(0.9, 0.95, 0.85, 1)\nambient_light_energy = 0.6\n\n[node name="PaperWindDemo" type="Node3D"]\n[node name="PaperWind" parent="." instance=ExtResource("1")]\n[node name="Camera3D" type="Camera3D" parent="."]\nposition = Vector3(0, 0, 7)\ncurrent = true\nfov = 37.0\n[node name="Light" type="DirectionalLight3D" parent="."]\nrotation_degrees = Vector3(-25, -25, 0)\nlight_energy = 1.8\n[node name="WorldEnvironment" type="WorldEnvironment" parent="."]\nenvironment = SubResource("Env")\n';
 const readme=`종이와 바람 / Godot 4 전달 패키지\n\n1. paper_wind 폴더 전체를 Godot 프로젝트의 res:// 아래로 복사하세요.\n2. PNG 가져오기가 끝나면 paper_wind/demo.tscn을 열고 F6으로 실행하세요.\n3. 게임에는 paper_wind/paper_wind.tscn을 인스턴스하여 배치하세요.\n4. Inspector에서 Wind Strength, Gust Variation, Fold Resistance, Wind Direction, Whole Sway를 조절합니다.\n5. 이 장면의 기본 높이는 ${height.toFixed(3)} Godot 단위입니다. 노드 Scale로 실제 포스터 크기에 맞추세요.\n\n이미지, 접힘, 고정점, 설정은 현재 웹 편집기의 값을 포함합니다. paper_data.gd가 실행 데이터이며 PNG와 함께 자동으로 게임에 포함됩니다. settings.json은 데이터 전달용 사본입니다. 웹 편집기로 다시 편집하려면 별도의 작업 저장 JSON을 사용하세요.\n\n웹과 같은 고정 60Hz 시뮬레이션으로 처음부터 재생합니다. 재질·조명과 플랫폼의 부동소수점 차이로 화면이 완전히 같지는 않을 수 있습니다.\n짧은 접힘 축은 종이 경계까지 연장됩니다. 교차 방향은 번갈아 움직입니다. 고정점이 접힘 양쪽에 있으면 해당 축은 움직이지 않습니다. 전체 흔들림은 고정점 1개 이하에서만 작동합니다. 자체 충돌과 게임플레이 충돌은 없습니다.\n\n성능 범위: 장면 인스턴스마다 활성 상태에서 변형 계산과 메시 갱신을 수행합니다. 텍스처는 리소스 캐시로 공유하고 메시·시뮬레이션 상태는 각 인스턴스가 소유합니다. 노드를 해제하면 해당 상태가 해제됩니다. 다수 포스터 배치 성능은 검증하지 않았습니다. 멀리 있는 포스터는 Playing을 끄거나 갱신 빈도를 관리하세요.\n\nGodot 4용이며 Godot 3에서는 실행할 수 없습니다. 기존 게임 세이브나 프로젝트 설정을 변경하지 않습니다.\n`;
 const readmeEnglish=`Paper & Wind / Godot 4 package

1. Copy the complete paper_wind folder into your Godot project's res:// directory.
2. Wait for the PNG import, open paper_wind/demo.tscn, and press F6.
3. Instance paper_wind/paper_wind.tscn in your game scene.
4. Change Wind Strength, Gust Variation, Fold Resistance, Wind Direction, and Whole Sway in the Inspector.
5. The default height is ${height.toFixed(3)} Godot units. Use the node Scale to match the intended poster size.

The package contains the current image, folds, pins, and settings. paper_data.gd is the runtime data and is included in Godot game exports through a preload dependency. settings.json is a reference copy. To edit in the web app again, save a web project JSON separately.

Playback restarts from time zero at a fixed 60 Hz, using the web simulation's equations. Lighting, materials, and floating-point differences can change the appearance. Fold axes extend to the sheet boundary. Crossing directions move in turn. A fold with pins on both sides is locked. Whole-sheet sway works with at most one pin. There is no self-collision or gameplay collision.

Each playing instance computes its own pose and updates its own mesh. The texture is shared through Godot's resource cache. Deleting the node releases its runtime state. Large numbers of posters have not been performance tested. Disable Playing for distant posters or manage update frequency in your game.

Tested with Godot 4.7.2. Godot 3 is unsupported. This package does not change game saves or project settings. The runtime code is MIT licensed; use only images you have permission to distribute.
`;
 return zipStore({'paper_wind/paper_wind.gd':await runtime.text(),'paper_wind/paper_data.gd':'extends RefCounted\nconst DATA = '+JSON.stringify(data)+'\n','paper_wind/settings.json':JSON.stringify(data,null,2),'paper_wind/paper.png':new Uint8Array(await png.arrayBuffer()),'paper_wind/paper_wind.tscn':scene,'paper_wind/demo.tscn':demo,'LICENSE.txt':await license.text(),'README.txt':getLanguage()==='en'?readmeEnglish:readme,'README.en.txt':readmeEnglish,'README.ko.txt':readme});
}
